+            continue;
+        }
+        let (run, pts, closed) = walk(v, ei, &mut used);
+        if let Some(arc) = fit_arc(&pts, closed, run) {
+            arcs.push(arc);
+        }
+    }
+
+    FeatureGraph { features, face_of_facet, faces, edges, points, arcs, chains: OnceLock::new(), runs: OnceLock::new() }
+}

