+    let reach = |depth: f64| match (q.ray.projection, hit) {
+        (Projection::Perspective, _) if per_depth > 0.0 => per_depth * depth,
+        (Projection::Perspective, Some((_, _, t))) if t > 0.0 => radius * depth / t,
+        _ => radius,
+    };
