+    assert_eq!(b.graph.points.len(), 8);
+    assert!(b.graph.points.iter().all(|p| p.kind == PointKind::Corner));
+    // Straight down onto the top face's diagonal (0,0)-(20,20).
+    for proj in [Projection::Ortho, Projection::Perspective] {
