+        q.through = true;
+        assert_eq!(pick_bodies(std::slice::from_ref(&b), &q), None, "not even picking through");
+        q.through = false;
+        q.kinds = PickKinds::ALL;
+        let pick = pick_bodies(std::slice::from_ref(&b), &q).expect("the face");
